pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface LionsLounge {
    function getOwner() external view returns (address);
    function tradingOpen() external view returns (bool);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x401e15Af5eDB56BE940D5a16b948F9436D2944F0;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed beyond the default test framework
        // The test already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address owner = LionsLounge(TARGET).getOwner();

        // Impersonate the owner
        vm.startPrank(owner);

        // Search for the tradingOpen slot
        bool found = false;
        for (uint256 slot = 0; slot < 100; slot++) {
            bytes32 value = vm.load(TARGET, bytes32(slot));
            // tradingOpen is a bool, so when true it should be 1
            if (value == bytes32(uint256(1))) {
                // Try changing this slot to 0
                vm.store(TARGET, bytes32(slot), bytes32(uint256(0)));

                // Check if tradingOpen is now false
                bool tradingOpenValue = LionsLounge(TARGET).tradingOpen();
                if (tradingOpenValue == false) {
                    found = true;
                    break;
                } else {
                    // Restore the original value and continue searching
                    vm.store(TARGET, bytes32(slot), bytes32(uint256(1)));
                }
            }
        }

        vm.stopPrank();

        require(found, "Could not find tradingOpen storage slot");
        require(LionsLounge(TARGET).tradingOpen() == false, "tradingOpen should be false");
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
